using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;
public static class RoomFixtureRepair {
 static bool Fixture(MeshFilter f)=>f.sharedMesh!=null&&Regex.IsMatch(f.sharedMesh.name,"Lamp|Candle|Torch|Light_|Chandelier",RegexOptions.IgnoreCase)&&!f.sharedMesh.name.Contains("Switch");
 static Material Unlit(Material m){if(m==null||m.name.EndsWith("_NoEmission")||!m.HasProperty("_EmissionColor"))return m;Directory.CreateDirectory("Assets/Generated/FixtureMaterials");string p="Assets/Generated/FixtureMaterials/"+m.name+"_NoEmission.mat";var variant=AssetDatabase.LoadAssetAtPath<Material>(p);if(variant==null){variant=new Material(m);variant.name=m.name+"_NoEmission";variant.SetColor("_EmissionColor",Color.black);variant.DisableKeyword("_EMISSION");variant.globalIlluminationFlags=MaterialGlobalIlluminationFlags.EmissiveIsBlack;AssetDatabase.CreateAsset(variant,p);}return variant;}
 public static string Run(){if(Application.isPlaying)throw new Exception("Edit Mode required");int rooms=0,decor=0,connected=0;var notes=new List<string>();foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/Building"})){string path=AssetDatabase.GUIDToAssetPath(guid);var root=PrefabUtility.LoadPrefabContents(path);bool dirty=false;try{if(root.GetComponent<Room>()==null)continue;rooms++;foreach(var mf in root.GetComponentsInChildren<MeshFilter>(true).Where(Fixture).ToArray()){
 if(mf.GetComponentInParent<LightObject>()!=null||mf.GetComponentInParent<RitualCandle>()!=null||mf.transform.GetComponentsInParent<Transform>().Any(t=>t.GetComponentInChildren<TorchLightFlicker>(true)!=null&&t.name.StartsWith("WallTorch")))continue;
 if(mf.transform.parent.GetComponentsInParent<MeshFilter>(true).Any(Fixture))continue;
 bool lamp=mf.sharedMesh.name.Contains("Lamp");bool decoration=!lamp||root.name=="B_Library";
 Transform fixture=mf.transform;if(mf.transform.parent.name.StartsWith("Desklamp"))fixture=mf.transform.parent;
 if(decoration){foreach(var r in fixture.GetComponentsInChildren<Renderer>(true)){r.sharedMaterials=r.sharedMaterials.Select(Unlit).ToArray();}foreach(var l in fixture.GetComponentsInChildren<Light>(true))l.enabled=false;foreach(var ps in fixture.GetComponentsInChildren<ParticleSystem>(true))ps.gameObject.SetActive(false);decor++;notes.Add(root.name+" decoration: "+fixture.name);dirty=true;continue;}
 var lightsParent=root.transform.Find("Objects/Lights");if(lightsParent==null||root.GetComponentsInChildren<LightSwitchInteractable>(true).Length==0)throw new Exception("No switch for "+root.name);
 var wrapper=new GameObject(fixture.name+" Switched Fixture");wrapper.transform.SetParent(lightsParent,false);fixture.SetParent(wrapper.transform,true);var lightGroup=new GameObject("Lights");lightGroup.transform.SetParent(wrapper.transform,false);
 var existing=fixture.GetComponentsInChildren<Light>(true);if(existing.Length>0){var positions=existing.Select(l=>l.transform.position).ToArray();foreach(var old in existing)UnityEngine.Object.DestroyImmediate(old);existing=positions.Select(position=>{var go=new GameObject("Switched Point Light");go.transform.SetParent(lightGroup.transform,false);go.transform.position=position;return go.AddComponent<Light>();}).ToArray();}else{var go=new GameObject("Point Light");go.transform.SetParent(lightGroup.transform,false);var glass=fixture.GetComponentsInChildren<Renderer>(true).FirstOrDefault(r=>r.name.Contains("Glass"));var render=glass??mf.GetComponent<Renderer>();go.transform.position=render.bounds.center+Vector3.up*(glass!=null?0:render.bounds.extents.y+.1f);existing=new[]{go.AddComponent<Light>()};}
 foreach(var l in existing){l.enabled=true;l.type=LightType.Point;l.lightmapBakeType=LightmapBakeType.Realtime;l.intensity=3;l.range=12;l.color=new Color(1,.83f,.6f);l.shadows=LightShadows.Hard;}
 var control=wrapper.AddComponent<LightObject>();var so=new SerializedObject(control);so.FindProperty("lights").objectReferenceValue=lightGroup;so.FindProperty("model").objectReferenceValue=fixture.gameObject;so.FindProperty("offEmissionColor").colorValue=Color.black;so.FindProperty("onEmissionColor").colorValue=Color.white;so.ApplyModifiedPropertiesWithoutUndo();connected++;dirty=true;notes.Add(root.name+" wired: "+fixture.name);
 }
 if(dirty){Directory.CreateDirectory("Temp/FixtureRepairBackup");var backup="Temp/FixtureRepairBackup/"+Path.GetFileName(path);if(!File.Exists(backup))File.Copy(path,backup);PrefabUtility.SaveAsPrefabAsset(root,path);}}finally{PrefabUtility.UnloadPrefabContents(root);}}AssetDatabase.SaveAssets();return rooms+" rooms audited; "+connected+" lamps wired; "+decor+" decorations made non-emissive\n"+string.Join("\n",notes);}
}

